#!/usr/bin/env python3
"""Produce a deterministic JSON fingerprint for a small workspace file."""

from __future__ import annotations

import hashlib
import json
import os
import stat
import sys

MAX_INPUT_BYTES = 4096


def fail(message: str) -> int:
    sys.stderr.write(f"error: {message}\n")
    return 1


def validate_relative_path(path: str) -> list[str]:
    if not path or os.path.isabs(path):
        raise ValueError("input path must be relative")

    components = path.split(os.sep)
    if any(component in ("", ".", "..") for component in components):
        raise ValueError("input path contains an invalid component")
    return components


def read_workspace_file(workspace: str, relative_path: str) -> bytes:
    components = validate_relative_path(relative_path)
    directory_flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NONBLOCK
    file_flags = os.O_RDONLY | os.O_NONBLOCK
    if hasattr(os, "O_CLOEXEC"):
        directory_flags |= os.O_CLOEXEC
        file_flags |= os.O_CLOEXEC
    if hasattr(os, "O_NOFOLLOW"):
        directory_flags |= os.O_NOFOLLOW
        file_flags |= os.O_NOFOLLOW

    current_fd = os.open(workspace, directory_flags)
    input_fd: int | None = None
    try:
        for component in components[:-1]:
            next_fd = os.open(component, directory_flags, dir_fd=current_fd)
            os.close(current_fd)
            current_fd = next_fd

        input_fd = os.open(components[-1], file_flags, dir_fd=current_fd)
        metadata = os.fstat(input_fd)
        if not stat.S_ISREG(metadata.st_mode):
            raise OSError("input is not a regular file")

        chunks: list[bytes] = []
        remaining = MAX_INPUT_BYTES + 1
        while remaining:
            chunk = os.read(input_fd, remaining)
            if not chunk:
                break
            chunks.append(chunk)
            remaining -= len(chunk)
        return b"".join(chunks)
    finally:
        if input_fd is not None:
            os.close(input_fd)
        os.close(current_fd)


def main(argv: list[str] | None = None) -> int:
    arguments = sys.argv[1:] if argv is None else argv
    if len(arguments) != 3 or arguments[0] != "--workspace":
        return fail("expected --workspace WORKSPACE RELATIVE_INPUT_PATH")

    workspace, relative_path = arguments[1:]
    try:
        data = read_workspace_file(workspace, relative_path)
    except (OSError, ValueError):
        return fail("unable to read input file")

    if len(data) > MAX_INPUT_BYTES:
        return fail("input exceeds 4096 bytes")

    try:
        text = data.decode("utf-8", errors="strict")
    except UnicodeDecodeError:
        return fail("input is not valid UTF-8")

    result = {
        "byte_count": len(data),
        "sha256": hashlib.sha256(data).hexdigest(),
        "text": text,
    }
    output = json.dumps(
        result,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    )
    sys.stdout.buffer.write(output.encode("utf-8") + b"\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
